type Order = { email: string; quantity: number; unitPrice: number };
type Services = { save(value: unknown): void; sendEmail(to: string, text: string): void; writeAudit(text: string): void };
export function processOrder(order: Order, services: Services) {
  if (order.quantity <= 0) throw new Error("Invalid quantity");
  if (!order.email.includes("@")) throw new Error("Invalid email");
  const normalized = { ...order, email: order.email.trim().toLowerCase() };
  const total = normalized.quantity * normalized.unitPrice;
  services.save({ ...normalized, total });
  services.sendEmail(normalized.email, "Order total: " + total);
  services.writeAudit(JSON.stringify({ kind: "order", total }));
  return total;
}

export type Order = { email: string; quantity: number; unitPrice: number };
export function prepareOrder(order: Order) {
  if (order.quantity <= 0) throw new Error("Invalid quantity");
  if (!order.email.includes("@")) throw new Error("Invalid email");
  return { ...order, email: order.email.trim().toLowerCase(), total: order.quantity * order.unitPrice };
}

import { prepareOrder, type Order } from "./prepare";
type Services = { save(value: ReturnType<typeof prepareOrder>): void; publish(value: ReturnType<typeof prepareOrder>): void };
export function processOrder(order: Order, services: Services) {
  const prepared = prepareOrder(order);
  services.save(prepared);
  services.publish(prepared);
  return prepared.total;
}

type Shipment = { paid: boolean; address: string; stock: number; quantity: number; blocked: boolean; expedited: boolean; overnight: boolean };
export function canShip(order: Shipment) {
  if (order.paid) {
    if (order.address.length > 0) {
      if (order.stock >= order.quantity) {
        if (!order.blocked) {
          if (order.expedited) {
            if (order.overnight) { return "overnight"; }
            else { return "express"; }
          } else { return "standard"; }
        } else { return null; }
      } else { return null; }
    } else { return null; }
  } else { return null; }
}

type Shipment = { paid: boolean; address: string; stock: number; quantity: number; blocked: boolean; expedited: boolean; overnight: boolean };
export function canShip(order: Shipment) {
  if (!order.paid || order.address.length === 0) return null;
  if (order.stock < order.quantity || order.blocked) return null;
  if (!order.expedited) return "standard";
  return order.overnight ? "overnight" : "express";
}

